struct dqblk dq_info;
const char *fs_path = "/dev/sdb1";
uid_t user_id = 501;
int ret;

// Turn USRQUOTA On
int cmd_on = QCMD(Q_QUOTAON, USRQUOTA);
ret = quotactl(cmd_on, fs_path, 0, NULL);

// Retrieve quota data for a user
int cmd_get = QCMD(Q_GETQUOTA, USRQUOTA);
ret = quotactl(cmd_get, fs_path, user_id, (caddr_t)&dq_info);

// Set new quota limits (requires setting dq_info fields)
int cmd_set = QCMD(Q_SETQUOTA, USRQUOTA);
ret = quotactl(cmd_set, fs_path, user_id, (caddr_t)&dq_info);

// Turn GRPQUOTA Off
int cmd_off = QCMD(Q_QUOTAOFF, GRPQUOTA);
ret = quotactl(cmd_off, fs_path, 0, NULL);
